const rates = [
  { from: "2026-08-01", naira: 1520 },
  { from: "2026-09-01", naira: 1610 },
];

function rateOn(rates, date) {
  let lo = 0;
  let hi = rates.length;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (rates[mid].from <= date) lo = mid + 1;
    else hi = mid;
  }
  return lo === 0 ? null : rates[lo - 1].naira;
}

console.log(["2026-07-31", "2026-08-01", "2026-08-31", "2026-09-15"].map((d) => String(rateOn(rates, d))).join(" "));

