function firstAndLast(sorted, value) {
  const bound = (strict) => {
    let lo = 0;
    let hi = sorted.length;
    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (sorted[mid] < value || (strict && sorted[mid] === value)) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  };
  const first = bound(false);
  const after = bound(true);
  return first === after ? [-1, -1] : [first, after - 1];
}

const stock = [2, 5, 5, 5, 7, 9];
console.log([5, 9, 6].map((v) => firstAndLast(stock, v).join(",")).join(" "));

